pub fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            let diff = b - a;
            match diff {
                0 => 0, // already equal
                d if d > 0 => {
                    // need to increase by (b - a) = d > 0
                    // can do any odd + in one move if d is odd, otherwise two moves
                    if d % 2 != 0 { 1 } else { 2 }
                }
                d => {
                    // need to decrease by (a - b) = -d > 0
                    // can do any even - in one move if (a - b) is even, otherwise two moves
                    let dec = -d;
                    if dec % 2 == 0 { 1 } else { 2 }
                }
            }
        })
        .collect()
}

